#pragma once

#include "nwcambientsound.h"

class CResGFF;
struct CResStruct;
class CSWSMessage;
template <class T> class CExoArrayList;

// The server-side ambient-sound emitter, one instance per area, owned by CSWSArea. It is a settings
// replicator and the server twin of CSWCAmbientSound, sharing the abstract root CSWAmbientSound
// that holds the settings block.
class CSWSAmbientSound : public CSWAmbientSound {
public:
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    virtual void PlayMusic(int);
    virtual void SetMusicDelay(int);
#if KOTOR1  // K1: no streaming flag
    virtual void SetMusicDayTrack(int nTrack);
    virtual void SetMusicNightTrack(int nTrack);
#else
    virtual void SetMusicDayTrack(int, int);
    virtual void SetMusicNightTrack(int, int);
#endif
    virtual void PlayBattleMusic(int);
    virtual void SetBattleMusicTrack(int);
    virtual void PlayAmbientSound(int);
    virtual void SetAmbientDayTrack(int);
    virtual void SetAmbientNightTrack(int);
    // </VTABLE-GEN>

    CSWSAmbientSound(unsigned long long nObjectId);

    // Collects into the list the player id of every connected player whose controlled creature stands in
    // this area, and returns that count, which the callers use as their loop bound.
    int GetPlayersInArea(CExoArrayList<unsigned long long>* pPlayers);

    // Loads the area's ambient-music/sound settings out of the .git's top-level struct.
    int Load(CResGFF* pGff, CResStruct* pStruct);

    // Requests the .git "Resource" 2DA row's cached sound; bStreaming selects the AmbientMusic
    // table over the AmbientSound one.
    void CacheSound(int nTrack, int bStreaming);

    // Writes the settings into the root of the save-properties struct.
    void Save(CResGFF* pGff, CResStruct* pStruct);

    // The CSWSMessage payload twin of Load.
    void PackIntoMessage(CSWSMessage* pMsg);

    // The two ambient volume setters are non-virtual; the NWScript volume commands call them
    // directly.
    void SetAmbientDayVolume(int nVolume);
    void SetAmbientNightVolume(int nVolume);

    unsigned long long m_oidArea;
};
